function timelineMarkup(){const p=db.projects.filter(x=>x.due).sort((a,b)=>a.due.localeCompare(b.due));return `<div class="timeline">${p.map(x=>`<div class="timeline-item"><div class="timeline-date">${fmt(x.due)} ${x.due<today()&&x.progress<100?'<span class="pill red">En retard</span>':''}</div><div class="item-title">${esc(x.name)}</div><div class="item-sub">${esc(x.status||'En cours')} · ${+x.progress||0}% terminé</div><div class="progress"><span style="width:${Math.max(0,Math.min(100,+x.progress||0))}%"></span></div></div>`).join('')}</div>`}
function noticeRow(n){return `<div class="notification ${n.read?'':'unread'}"><div class="notice-icon">${n.type==='danger'?'!':n.type==='warning'?'◷':'♧'}</div><div class="item-main"><div class="item-title">${esc(n.title)}</div><div class="item-sub">${esc(n.message)}</div><time>${new Date(n.createdAt).toLocaleString('fr-FR')}</time></div><div class="item-actions">${!n.read?`<button class="small-btn" data-read="${n.id}">Lu</button>`:''}<button class="small-btn" data-del-notice="${n.id}">×</button></div></div>`}
function field(label,name,type='text',value='',opts=null,required=false){let inner=type==='select'?`<select name="${name}" ${required?'required':''}>${opts.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${name}">${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}>`;return `<div class="field"><label>${label}</label>${inner}</div>`}
function openModal(title,fields,onSave){$('#modalTitle').textContent=title;$('#modalEyebrow').textContent='UNIVERSE · FORMULAIRE';$('#modalBody').innerHTML=`<div class="form-grid">${fields}</div>`;const form=$('#modalForm');form.onsubmit=e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const d=Object.fromEntries(new FormData(form).entries());if(onSave(d)===false)return;$('#modal').close();save();render()};$('#modal').showModal()}
